test("selectors return exact structure for each screen", () => {
  const screen01 = selectPitchScreen01();
  assert.equal(screen01.route, PITCH_ROUTE_DOUBLE_ENGINE);
  assert.equal(screen01.split.leftPercent, 50);
  assert.equal(screen01.split.rightPercent, 50);
  assert.equal(screen01.motors[0]?.motorId, "motor1");
  assert.equal(screen01.motors[1]?.motorId, "motor2");
  assert.equal(screen01.motors[0]?.widthPercent, 50);
  assert.equal(screen01.motors[1]?.widthPercent, 50);
  assert.equal(screen01.motors[0]?.bullets.length, 5);
  assert.equal(screen01.motors[1]?.bullets.length, 6);

  const screen02 = selectPitchScreen02();
  assert.equal(screen02.route, PITCH_ROUTE_INDUSTRIAL_FLOW);
  assert.equal(screen02.kpiWidgets.length, 5);
  assert.equal(screen02.cycleWidget.months, 35);
  assert.equal(screen02.cycleWidget.points.length, 35);
  assert.equal(screen02.cycleWidget.resetBehavior, "automatic");
  assert.equal(screen02.annualization.annualProfitUsd, 1092000);

  const screen03 = selectPitchScreen03();
  assert.equal(screen03.route, PITCH_ROUTE_HITECH_OS);
  assert.equal(screen03.features.length, 7);
  assert.equal(screen03.features[0]?.id, "feature-01");

  const screen04 = selectPitchScreen04();
  assert.equal(screen04.route, PITCH_ROUTE_VALUATION);
  assert.equal(screen04.blocks.blockOne.length, 4);
  assert.equal(screen04.blocks.blockTwo.length, 5);
  assert.equal(screen04.blocks.blockThree.length, 2);
  assert.equal(screen04.table.headers.length, 4);
  assert.equal(screen04.table.rows.length, 2);
  assert.equal(screen04.impliedIndustrialValuation.low, 2184000);
  assert.equal(screen04.impliedIndustrialValuation.high, 3276000);
});

test("selectors by route remain deterministic over large matrix", () => {
  for (const testCase of ROUTE_EXPECTATION_CASES) {
    const screen = selectPitchScreenByRoute(testCase.route);
    assert.equal(screen.route, testCase.route, testCase.id);
    assert.notEqual(screen.title.trim(), "", `${testCase.id}: empty title`);
  }
});

test("bundle is coherent for all screens", () => {
  const bundle = selectPitchBundle();
  assert.equal(bundle.orderedScreens.length, 4);
  assert.equal(bundle.screen01.route, PITCH_ROUTE_DOUBLE_ENGINE);
  assert.equal(bundle.screen02.route, PITCH_ROUTE_INDUSTRIAL_FLOW);
  assert.equal(bundle.screen03.route, PITCH_ROUTE_HITECH_OS);
  assert.equal(bundle.screen04.route, PITCH_ROUTE_VALUATION);

  assert.equal(bundle.screen01.motors[0]?.slot, "left");
  assert.equal(bundle.screen01.motors[1]?.slot, "right");

  const cycleLast = bundle.screen02.cycleWidget.points[bundle.screen02.cycleWidget.points.length - 1];
  assert.equal(cycleLast?.servicedModulesInCycle, 420);
  assert.equal(cycleLast?.cycleCompleted, true);

  assert.equal(bundle.screen03.features[6]?.id, "feature-07");
  assert.equal(bundle.screen04.table.rows[1]?.model, "Industrial + Software");
});

